import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter/material.dart';
import '../../../../core/theme/app_theme.dart';
class ArticleDetailScreen extends StatelessWidget { const ArticleDetailScreen({super.key,this.slug}); final String? slug; @override Widget build(BuildContext context){if(slug==null)return const Scaffold(body:Center(child:Text('Lesson not found')));return Scaffold(backgroundColor:PennyPalColors.black,appBar:AppBar(backgroundColor:PennyPalColors.black,title:const Text('Lesson',style:TextStyle(color:Colors.white))),body:StreamBuilder<DocumentSnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('learningContent').doc(slug).snapshots(),builder:(_,s){if(s.hasError)return Center(child:Text('${s.error}',style:const TextStyle(color:Colors.white)));if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!.data();if(d==null)return const Center(child:Text('This lesson is unavailable.',style:TextStyle(color:PennyPalColors.gray)));return SingleChildScrollView(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${d['title']??''}',style:const TextStyle(color:Colors.white,fontSize:26,fontWeight:FontWeight.w800)),const SizedBox(height:12),Text('${d['category']??''}',style:const TextStyle(color:PennyPalColors.gray)),const SizedBox(height:28),Text('${d['content']??d['summary']??''}',style:const TextStyle(color:Colors.white,fontSize:16,height:1.6))]));}));}}
